users = list_users({})
user_ids = for u in users { return u.id }
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

# For each user and date, get availability in parallel
avail = for u in user_ids {
  days = for d in dates {
    a = boundary retry 2 {
      return get_availability({ user_id: u, date: d })
    } catch err {
      return fail("AVAIL", err.code + ": " + err.message)
    }
    return { date: d, busy: a.busy if a.busy != null else [] }
  }
  return { user_id: u, days: days }
}

# Possible start times: 09:00, 09:30, ..., 16:00 (meeting ends by 17:00)
# Represent times as minutes from midnight
starts_mins = [540, 570, 600, 630, 660, 690, 720, 750, 780, 810, 840, 870, 900, 930, 960]
# 540=09:00 ... 960=16:00

pad2 = (n) => {
  s = json.encode(n)
  return s if text.length(s) >= 2 else "0" + s
}

# Check if a time range [start_m, end_m) overlaps any busy interval
# busy intervals are {start: "HH:MM", end: "HH:MM"}

parse_hm = (hm) => {
  parts = text.split(hm, ":")
  h = number.parse(parts[0])
  m = number.parse(parts[1])
  return h * 60 + m
}

# For each date in order, for each start time, check if all users are free
result = fold acc = null for d in dates {
  skip if acc != null
  found = fold inner = null for sm in starts_mins {
    skip if inner != null
    em = sm + 60
    # check all users free
    conflicts = fold c = 0 for u in avail {
      day = fold found_day = null for dd in u.days {
        skip if dd.date != d
        return dd
      }
      busy_list = day.busy if day != null else []
      hit = fold h = 0 for b in busy_list {
        bs = parse_hm(b.start)
        be = parse_hm(b.end)
        # overlap if sm < be and em > bs
        ov = sm < be and em > bs
        return h + 1 if ov else h
      }
      return c + hit
    }
    return { date: d, start_m: sm, end_m: em } if conflicts == 0 else null
  }
  return found
}

assert(result != null, "no slot found")

sh = number.floor(result.start_m / 60)
sm = result.start_m - sh * 60
eh = number.floor(result.end_m / 60)
em = result.end_m - eh * 60

shs = text.slice("0" + json.encode(sh), -2, 100)
sms = text.slice("0" + json.encode(sm), -2, 100)
ehs = text.slice("0" + json.encode(eh), -2, 100)
ems = text.slice("0" + json.encode(em), -2, 100)

start_iso = result.date + "T" + shs + ":" + sms + ":00Z"
end_iso = result.date + "T" + ehs + ":" + ems + ":00Z"

sub = submit_result({ answer: { start: start_iso, end: end_iso } })
return { start: start_iso, end: end_iso, recorded: sub.recorded, users: user_ids, avail: avail }

users = list_users({})
user_ids = for u in users { return u.id }
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
starts_mins = [540, 570, 600, 630, 660, 690, 720, 750, 780, 810, 840, 870, 900, 930, 960]

avail = for u in user_ids {
  days = for d in dates {
    a = boundary retry 2 {
      return get_availability({ user_id: u, date: d })
    } catch err {
      return fail("AVAIL", err.code + ": " + err.message)
    }
    return { date: d, busy: a.busy if a.busy != null else [] }
  }
  return { user_id: u, days: days }
}

# Build candidate slots earliest-first: date then start minute
candidates = fold acc = [] for d in dates {
  day_slots = for sm in starts_mins {
    return { date: d, start_m: sm, end_m: sm + 60 }
  }
  return acc + day_slots
}

# Find first slot where every user is free
result = fold acc = null for slot in candidates {
  skip if acc != null
  conflicts = fold c = 0 for u in avail {
    day_info = fold found_day = null for dd in u.days {
      skip if dd.date != slot.date
      return dd
    }
    busy_list = day_info.busy if day_info != null else []
    hit = fold h = 0 for b in busy_list {
      bparts_s = text.split(b.start, ":")
      bparts_e = text.split(b.end, ":")
      bs = number.parse(bparts_s[0]) * 60 + number.parse(bparts_s[1])
      be = number.parse(bparts_e[0]) * 60 + number.parse(bparts_e[1])
      ov = slot.start_m < be and slot.end_m > bs
      return h + 1 if ov else h
    }
    return c + hit
  }
  return slot if conflicts == 0 else null
}

assert(result != null, "no slot found")

sh = number.floor(result.start_m / 60)
smins = result.start_m - sh * 60
eh = number.floor(result.end_m / 60)
emins = result.end_m - eh * 60

shs = text.slice("0" + json.encode(sh), -2, 100)
sms = text.slice("0" + json.encode(smins), -2, 100)
ehs = text.slice("0" + json.encode(eh), -2, 100)
ems = text.slice("0" + json.encode(emins), -2, 100)

start_iso = result.date + "T" + shs + ":" + sms + ":00Z"
end_iso = result.date + "T" + ehs + ":" + ems + ":00Z"

sub = submit_result({ answer: { start: start_iso, end: end_iso } })
return { start: start_iso, end: end_iso, recorded: sub.recorded }
